:"77ab171c-21eb-4ad7-807f-a1280731a291","max_sort":35,"net":"Subnet 172.16.8.x","blocks":[16,38,39,40,41,42]},{"uuid":"f57fa328-33f3-42d9-8be4-f2c3b4c39251","max_sort":35,"net":"Subnet 172.16.10.x","blocks":[30,31,32,18,33,34,35,36,37]},{"uuid":"6638e708-3f51-4f07-a962-6ce3260fd5e3","max_sort":35,"net":"Subnet 172.16.10.x","blocks":[16,38,39,40,41,42]},{"uuid":"030129b1-7be5-5ebc-835e-78d7648a046e","max_sort":35,"net":"Subnet 172.16.11.x","blocks":[16,43,44,38,18,45,46,47,48,49]},{"uuid":"2da3518f-9a1c-44bd-a304-1c39a9cb88e4","max_sort":35,"net":"Subnet 172.16.12.x","blocks":[16,43,44,38,18,45,46,47,48,49]},{"uuid":"6e88d2dc-27bd-5545-9939-e10b5dcde4d8","max_sort":35,"net":"Subnet 172.16.9.x","blocks":[30,31,32,18,16,38,39,50,34,35,36,37,41,42]}],"templates":[{"uuid":"68943ccc-3318-5009-8c4e-39f6effa5c50","name":"SAS · Trafo Protection (=ETxx+R1)","net":"Subnet 172.16.<no. bay>.x","blocks":[30,31,32,18,33,34,35,36,37]},{"uuid":"7500c862-6333-5e88-9854-5d5df5d86458","name":"SAS · Trafo Control (=ETxx+W1)","net":"Subnet 172.16.<no. bay>.x","blocks":[16,38,39,40,41,42]},{"uuid":"9b2fb8a4-d086-52ea-a5c1-f0a93416e65e","name":"SAS · UGC Control & Protection (=EUxx+WR1)","net":"Subnet 172.16.<no. bay>.x","blocks":[16,43,44,38,18,45,46,47,48,49]},{"uuid":"56ada01e-df25-57ba-aaa8-9f4413bae161","name":"SAS · Bus Coupler / Bus Section (=ECxx/ESxx+WR1)","net":"Subnet 172.16.<no. bay>.x","blocks":[16,17,18,19,20,21,22]},{"uuid":"03b6908c-95d4-5b63-a746-3116c1339a32","name":"SAS · Busbar Protection (=E00+R1/R2)","net":"Subnet 172.16.<no. bay>.x","blocks":[0,1,2,3,4,5,6]},{"uuid":"331d365e-8d10-5a8b-aae6-3d0899872260","name":"SAS · Common IED I/O (=E00+X1/X2)","net":"Subnet 172.16.<no. bay>.x","blocks":[7,8]},{"uuid":"181ef136-5085-5de1-a774-024b4791b966","name":"SAS · SAS 1 Panel / Gateway (=E00+X3)","net":"Sesuai IP plan","blocks":[9,10,11,12]},{"uuid":"d80e3841-03df-5032-87d7-9f0913bedb5d","name":"SAS · SAS 2 Panel / Gateway (=E00+X4)","net":"Sesuai IP plan","blocks":[13,14,15]}]}$sas$::jsonb j),
titems as (
  select t->>'uuid' tu, t->>'name' tn,
         jsonb_agg(jsonb_build_array(substr(d.j->>'letters', bo::int, 1) || '. SAS · ' || (d.j->'blocks'->(b::int)->>'name'),
                   it->>0, replace(it->>1, '{net}', t->>'net'), it->>2) order by bo, io) items
  from d, jsonb_array_elements(d.j->'templates') t,
       jsonb_array_elements_text(t->'blocks') with ordinality as bl(b, bo),
       jsonb_array_elements(d.j->'blocks'->(b::int)->'items') with ordinality as its(it, io)
  group by 1, 2),
tpl as (
  insert into public.check_templates(uuid,name,description,items,created_at,updated_at,deleted)
  select tu::uuid, tn, (select j->>'desc' from d), items, (select j->>'local' from d), (select j->>'stamp' from d), 0
  from titems
  on conflict (uuid) do update set items = excluded.items, description = excluded.description,
                                   updated_at = excluded.updated_at, deleted = 0
  returning 1),
rows as (
  select p->>'uuid' pu, (p->>'max_sort')::int ms, p->>'net' net,
         substr(d.j->>'letters', bo::int, 1) || '. SAS · ' || (d.j->'blocks'->(b::int)->>'name') sec, it, bo, io
  from d, jsonb_array_elements(d.j->'panels') p,
       jsonb_array_elements_text(p->'blocks') with ordinality as bl(b, bo),
       jsonb_array_elements(d.j->'blocks'->(b::int)->'items') with ordinality as its(it, io)),
newrows as (
  select extensions.uuid_generate_v5((select (j->>'ns')::uuid from d), pu || '|' || sec || '|' || (it->>0)) cu, *
  from rows),
old as (
  update public.panel_checks c set deleted = 1, updated_at = (select j->>'stamp' from d)
  where c.section like '_. SAS · %' and c.deleted = 0
    and coalesce(c.result,'') = '' and coalesce(c.value,'') = '' and coalesce(c.remark,'') = ''
    and c.uuid not in (select cu from newrows)
    and c.panel_uuid in (select (p->>'uuid')::uuid from d, jsonb_array_elements(d.j->'panels') p)
  returning 1),
ins as (
  insert into public.panel_checks(uuid,panel_uuid,section,description,criteria,unit,sort,result,value,remark,
                                  checked_by,checked_at,created_at,updated_at,deleted)
  select cu, pu::uuid, sec, it->>0, replace(it->>1, '{net}', net), it->>2,
         ms + row_number() over (partition by pu order by bo, io), '', '', '', '', null,
         (select j->>'local' from d), (select j->>'stamp' from d), 0
  from newrows
  on conflict (uuid) do nothing returning 1)
select (select count(*) from tpl) template_diperbarui, (select count(*) from old) item_lama_dihapus,
       (select count(*) from ins) item_baru;
